--
-- Table structure for table `data_penduduk`
--

CREATE TABLE `data_penduduk` (
  `id_penduduk` int(10) UNSIGNED NOT NULL,
  `id_kecamatan` int(10) UNSIGNED DEFAULT NULL,
  `id_admin` int(10) UNSIGNED DEFAULT NULL,
  `tahun` year(4) NOT NULL,
  `jenis_data` enum('kecamatan','kabupaten') NOT NULL DEFAULT 'kecamatan',
  `jumlah_penduduk_kecamatan` int(10) UNSIGNED DEFAULT NULL,
  `jumlah_penduduk_kabupaten` int(10) UNSIGNED NOT NULL,
  `sumber_data` varchar(100) DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

